SELECT 'gongkao', '完成标准变化', 'kp-eng-ct-std-change', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "完成标准变化"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "工程总量 W 发生了突变。必须重新计算剩余工作量。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“修路到一半，接到上级通知，不仅要修完原定的路，还要额外再延伸修 5 公里”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破局"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这种题目最忌讳在原有的特值 W 上直接加绝对数量（比如特值设了60，加上绝对的5公里，60+5=65 彻底乱套）。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[遇到工程量中途增加绝对数值] --> B[放弃纯比例的最小公倍数赋值法!]\nB --> C[老老实实设原计划每天的真实工程量为 X]\nC --> D[原总量 = 计划天数 * X]\nD --> E[新总量 = 原总量 + 额外增加的量]\nE --> F[根据题目后续的时间条件列出真实的一元一次方程]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 工程队计划 20 天修完路。干了 5 天后，增加修路任务 300 米。为了按期完工，他们将效率提升了 20%。问原计划每天修多少米？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "设未知数：绝不能用公倍数赋 W。设原计划每天修 x 米。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "梳理残局：剩下 15 天的原计划工作量是 15x。加上新增的 300，剩下的总活是 15x + 300。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "推导新效率：效率提升 20%，现在每天修 1.2x 米。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "列死线方程：要求“按期完工”（即还是用剩下的 15 天）。所以：(15x + 300) / 1.2x = 15。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "解方程：15x + 300 = 18x。3x = 300，x = 100。原计划每天修 100 米。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "虚拟份数与绝对量混用：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "在没给具体产量的题里，我们可以随便假设总量为 60 份。但一旦题目里出现了“增加了 300 米”、“多加工了 50 个”这种绝对客观物理量，特值法瞬间失效，必须立刻切换成设未知数 x 的方程思维！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "练就“识破伪装”的能力。扫一眼题目，只要有具体的千克、米、件等单位，立刻抛弃最小公倍数法，拿出 x。"}]}]}$$ AS jsonb), NULL, '完成标准变化的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "完成标准变化"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_ct_std_change", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
